extends Node3D
class_name LSystemTree

@export var iterations: int = 4
@export var base_angle: float = 25.7  # Lindenmayer's original
@export var base_length: float = 0.1

const AXIOM := "F"
const RULES := {
	"F": "F[+F]F[-F]F"
	# Other examples:
	#   "F": "FF[+F]F[-F]F"       # taller, skinnier
	#   "F": "F[+F][-F]F"          # sparse
	#   "F": "F[+F-F]F[-F+F]F"     # kinked
}

func _render_lines(lines: Array) -> void:
	var im = ImmediateMesh.new()
	im.surface_begin(Mesh.PRIMITIVE_LINES)

	for line in lines:
		var start = line[0]
		var end = line[1]
		var depth = line[2] if line.size() > 2 else 0  # depth in bracket stack

		# Depth 0 = trunk (brown), deeper = greener
		var t = float(depth) / float(iterations)
		var color = trunk_color.lerp(tip_color, t)

		im.surface_set_color(color)
		im.surface_add_vertex(start)
		im.surface_set_color(color)
		im.surface_add_vertex(end)

	im.surface_end()
	_line_mesh.mesh = im

@export var iterations: int = 4     # 1–5 reasonable, >5 explodes
@export var base_angle: float = 25.7  # 10–45 reasonable
@export var base_length: float = 0.1 # scale of each F segment

func apply_grid_config(config: Dictionary) -> void:
	if config.has("iterations"):
		iterations = clampi(int(config["iterations"]), 1, 6)
	if config.has("base_angle"):
		base_angle = float(config["base_angle"])
	if config.has("base_length"):
		base_length = float(config["base_length"])
	rebuild()

func rebuild() -> void:
	_clear()
	var s = _derive_string()
	var lines = _interpret(s)
	_render_lines(lines)
